/* Cover-first galleries. Draft selections are applied only by explicit confirmation. */
(function(){let disposers=[];const motion=()=>window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;function dispose(){disposers.forEach(fn=>fn());disposers=[]}function mount(root){dispose();root.querySelectorAll('.selection-preview:not([hidden]),[data-destination-gallery]').forEach(node=>{const images=[...node.querySelectorAll('img')];if(!images.length)return;let index=0,paused=false,hover=false,focus=false,visible=false,request=0,timer,fadeTimer;const count=node.querySelector('[data-count]'),pause=node.querySelector('[data-pause]');function stop(){clearInterval(timer)}function show(n){const next=(n+images.length)%images.length,img=images[next],version=++request;if(!img.getAttribute('src')&&img.dataset.src){img.loading='eager';img.src=img.dataset.src}if(next!==index&&(!img.complete||!img.naturalWidth)){img.decode().then(()=>{if(version===request)applyShow(next)}).catch(()=>{});return}applyShow(next)}function applyShow(n){const previous=index;index=(n+images.length)%images.length;clearTimeout(fadeTimer);images.forEach((img,i)=>{img.classList.remove('gallery-leaving','gallery-current');img.hidden=i!==index;if(i===index)img.classList.add('gallery-current');if(i===previous&&previous!==index&&!motion())img.classList.add('gallery-leaving');if(i===index&&previous!==index&&!motion())img.animate?.([{opacity:0},{opacity:1}],{duration:750,easing:'ease-out'});});fadeTimer=setTimeout(()=>images.forEach(img=>img.classList.remove('gallery-leaving')),780);if(count)count.textContent=(index+1)+' / '+images.length;const sources=node.parentElement.querySelector('.gallery-source-links');if(sources)sources.querySelectorAll('[data-source-index]').forEach(link=>link.hidden=Number(link.dataset.sourceIndex)!==index);}

function start(){stop();if(visible&&images.length>1&&!paused&&!hover&&!focus&&!document.hidden&&!motion())timer=setInterval(()=>show(index+1),5000)}function listen(target,event,fn){target.addEventListener(event,fn);disposers.push(()=>target.removeEventListener(event,fn))}listen(node,'mouseenter',()=>{hover=true;stop()});listen(node,'mouseleave',()=>{hover=false;start()});listen(node,'focusin',()=>{focus=true;stop()});listen(node,'focusout',event=>{if(!node.contains(event.relatedTarget)){focus=false;start()}});listen(document,'visibilitychange',start);node.querySelectorAll('[data-prev],[data-next]').forEach(btn=>listen(btn,'click',event=>{event.preventDefault();event.stopPropagation();show(index+(btn.hasAttribute('data-next')?1:-1));start()}));if(pause)listen(pause,'click',()=>{paused=!paused;pause.textContent=paused?(document.documentElement.lang==='en'?'Resume slideshow':'继续轮播'):(document.documentElement.lang==='en'?'Pause slideshow':'暂停轮播');pause.setAttribute('aria-pressed',String(paused));start()});const mq=window.matchMedia?.('(prefers-reduced-motion: reduce)');if(mq?.addEventListener)listen(mq,'change',start);const observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;start()});observer.observe(node);disposers.push(()=>{request++;observer.disconnect()});show(0);start();disposers.push(()=>{stop();clearTimeout(fadeTimer)})});}
function photos(d){let saved;try{saved=JSON.parse(localStorage.getItem('yichen-destination-galleries-v9')||'{}')[d.id]}catch{}const valid=Array.isArray(saved)?saved.filter(p=>typeof p.src==='string'&&/^\.\/images\//.test(p.src)):[];return valid.length?valid:(d.gallery?.length?d.gallery:[{src:d.image,label:d.name}]);}
window.DestinationGallery={mount,dispose,photos};})();
